import{_ as o,o as r,c as s,ae as i}from"./chunks/framework.Dh1jimFm.js";const p=JSON.parse('{"title":"Web Resources","description":"","frontmatter":{},"headers":[],"relativePath":"superlookup/web-resources.md","filePath":"superlookup/web-resources.md"}'),a={name:"superlookup/web-resources.md"};function l(t,e,n,c,u,d){return r(),s("div",null,e[0]||(e[0]=[i('<h1 id="web-resources" tabindex="-1">Web Resources <a class="header-anchor" href="#web-resources" aria-label="Permalink to &quot;Web Resources&quot;">​</a></h1><p>Superlookup’s <strong>Web Resources</strong> tab gives you a one-click sidebar of reference sites for terminology and research.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>You use the <strong>main Superlookup search box</strong> (top of the window) and click <strong>Search</strong>.</li><li>The Web Resources tab uses your <strong>From → To</strong> language direction when building URLs.</li></ul><h2 id="browser-modes" tabindex="-1">Browser modes <a class="header-anchor" href="#browser-modes" aria-label="Permalink to &quot;Browser modes&quot;">​</a></h2><p>In the left sidebar you can choose a mode:</p><ul><li><strong>Embedded:</strong> opens sites inside Supervertaler (requires <code>QtWebEngine</code>). <ul><li>Uses a persistent browser profile so logins/cookies are kept between sessions.</li></ul></li><li><strong>External:</strong> opens your default browser.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When Embedded mode is available, Superlookup can pre-load searches for all resources at once.</p></div><h2 id="search-options" tabindex="-1">Search options <a class="header-anchor" href="#search-options" aria-label="Permalink to &quot;Search options&quot;">​</a></h2><ul><li>Select a single resource (e.g. IATE) and click <strong>Search</strong>.</li><li>Click <strong>Search All</strong> to load results for all resources (Embedded mode).</li><li>Use <strong>Open in Browser</strong> to open the last search URL in your default browser.</li></ul><h2 id="included-resources" tabindex="-1">Included resources <a class="header-anchor" href="#included-resources" aria-label="Permalink to &quot;Included resources&quot;">​</a></h2><p>The sidebar includes (by default):</p><ul><li>IATE</li><li>Linguee</li><li>ProZ.com</li><li>Reverso Context</li><li>Google Search</li><li>Google Patents</li><li>Wikipedia (Source)</li><li>Wikipedia (Target)</li><li>Juremy</li><li>michaelbeijer.co.uk</li><li>AcronymFinder</li><li>BabelNet</li><li>Wiktionary (Source)</li><li>Wiktionary (Target)</li></ul><h2 id="show-hide-resources" tabindex="-1">Show/hide resources <a class="header-anchor" href="#show-hide-resources" aria-label="Permalink to &quot;Show/hide resources&quot;">​</a></h2><p>In <strong>Superlookup → Settings → Web Resources</strong>, you can toggle which sites appear in the sidebar.</p>',15)]))}const b=o(a,[["render",l]]);export{p as __pageData,b as default};
